'use strict';
const language=document.documentElement.lang;const ar=language==='ar';
const tabs=[...document.querySelectorAll('[data-value]')];function selectValue(i,focus=false){tabs.forEach((tab,index)=>{tab.setAttribute('aria-selected',String(index===i));tab.tabIndex=index===i?0:-1;document.querySelector('#value-panel-'+index).hidden=index!==i});if(focus)tabs[i].focus()}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectValue(i));tab.addEventListener('keydown',e=>{let next=i;if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else if(['ArrowLeft','ArrowRight'].includes(e.key)){const delta=(e.key==='ArrowRight'?1:-1)*(ar?-1:1);next=(i+delta+tabs.length)%tabs.length}else return;e.preventDefault();selectValue(next,true)})});
const routes=[...document.querySelectorAll('[data-route]')];const recommendations=ar?{build:'بناء أعمال جديدة بمنطق سوقي أوضح، وهيكل تشغيلي منظم، وانضباط أكبر في الإطلاق.',transform:'تطوير الأعمال القائمة من خلال التشخيص، وإعادة الهيكلة، والتحسين المنسق.',scale:'بناء الحوكمة والقدرات ووضوح الأداء اللازم لتحقيق نمو منضبط وقابل للإدارة.'}:{build:'Create new businesses with clearer market logic, operating structure and launch discipline.',transform:'Strengthen existing businesses through diagnosis, restructuring and coordinated improvement.',scale:'Build the governance, capability and performance visibility required for controlled growth.'};routes.forEach(button=>button.addEventListener('click',()=>{const route=button.dataset.route;routes.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('#route-recommendation').textContent=recommendations[route];document.querySelector('#route-detail').href='/'+language+'/'+route+'/';document.querySelector('#route-enquiry').href='/'+language+'/contact/?route='+route}));
document.querySelectorAll('[data-cap]').forEach(button=>button.addEventListener('click',()=>syncLines()));document.querySelectorAll('[data-cap]').forEach(button=>button.addEventListener('keydown',()=>queueMicrotask(syncLines)));function syncLines(){const active=document.querySelector('.cap-node[aria-pressed=true]')?.dataset.cap;document.querySelectorAll('[data-cap-line]').forEach(line=>line.classList.toggle('active',line.dataset.capLine===active))}
const video=document.querySelector('[data-hero-video]');const toggle=document.querySelector('#video-toggle');if(video&&toggle){video.muted=true;function syncVideo(){const playing=!video.paused;toggle.setAttribute('aria-pressed',String(playing));toggle.textContent=ar?(playing?'إيقاف فيديو الخلفية':'تشغيل فيديو الخلفية'):(playing?'Pause background video':'Play background video')}
video.addEventListener('play',syncVideo);video.addEventListener('pause',syncVideo);video.addEventListener('error',()=>{toggle.hidden=true;video.style.background="url('/assets/orbit-video-poster.webp') center/cover"});toggle.addEventListener('click',()=>{if(video.paused)video.play().catch(syncVideo);else video.pause()});const motion=matchMedia('(prefers-reduced-motion: reduce)');const constrained=!!navigator.connection?.saveData;if(!motion.matches&&!constrained)video.play().catch(syncVideo);motion.addEventListener?.('change',e=>{if(e.matches)video.pause()});syncVideo();}
const brief=document.querySelector('#brief');if(brief&&brief.querySelector('[data-brief-step]')){const steps=[...brief.querySelectorAll('[data-brief-step]')];const progress=[...brief.querySelectorAll('.brief-progress li')];let step=0;const next=brief.querySelector('#brief-next'),back=brief.querySelector('#brief-back'),submit=brief.querySelector('#brief-submit');function show(i,focus=true){step=i;steps.forEach((s,index)=>s.hidden=index!==i);progress.forEach((p,index)=>{if(index===i)p.setAttribute('aria-current','step');else p.removeAttribute('aria-current')});next.hidden=i===2;submit.hidden=i!==2;back.hidden=i===0;if(focus)steps[i].querySelector('input,textarea')?.focus()}
function valid(i){for(const control of steps[i].querySelectorAll('input,textarea')){if(!control.checkValidity()){show(i);control.reportValidity();return false}}return true}
next.addEventListener('click',()=>{if(valid(step))show(step+1)});back.addEventListener('click',()=>show(Math.max(0,step-1)));brief.addEventListener('submit',e=>{for(let i=0;i<steps.length;i++)if(!valid(i)){e.preventDefault();e.stopImmediatePropagation();return}},true);const prefill=new URLSearchParams(location.search).get('route');if(['build','transform','scale'].includes(prefill))brief.querySelector('input[name=route][value='+prefill+']').checked=true;show(0,false);}
